        "key_number": "Qwen3-235B 温度 0：1000 次采样 80 种不同输出 → 1 种；逐位一致训练 KL 恒为 0",
        "systems": "vLLM、SGLang 的确定性 / batch-invariant 模式；VeRL / slime / OAT 集成 TIS"
