        "key_number": "LMCache 吞吐最高 15×、CPU 卸载带宽 400 Gbps（vLLM 原生 88）；Strata 长上下文最高 5×（对 vLLM+LMCache）/ 3.75×（对 TensorRT-LLM）",
        "systems": "LMCache（vLLM / SGLang 连接器）；SGLang HiCache（HiRadixTree）；Mooncake Store；DeepSeek-V4 的磁盘 KV 缓存"
